          // helpful for GTM debugging\n        enhanced_conversion_data: { email: normalisedEmail }  // unhashed\n      });\n    }\n\n    /* 3. Fire the webhook.  Whatever happens, redirect afterwards. */\n    fetch('https://nucleus.default.com/webhooks/387242', {\n      method:  'POST',\n      headers: { 'Content-Type': 'application/json' },\n      body:    JSON.stringify(jsonData),\n      keepalive: true              // lets the request finish even on navigation\n    })\n    .catch(err => console.error('Webhook failed:', err))\n    .finally(() => {\n      // always navigate; don’t strand the user\n      window.location.href = `/demo?email=${encodeURIComponent(jsonData.email || '')}`;\n    });\n  });\n})();\n</script></div><div class=\"am-form-submit-wrapper\"><div class=\"am-nav-btn-wrapper\"><input type=\"submit\" data-wait=\"Please wait...\" data-btn-color-mode=\"dark\" class=\"am-nav-btn business-only-submit-button is-full-size-mobile w-button\" value=\"Get free trial\" /><div class=\"am-nav-btn-rocket\"><div class=\"am-paragraph-20\">🚀</div></div></div></div></form><div class=\"am-form-success-message w-form-done\" tabindex=\"-1\" role=\"region\" aria-label=\"Partial - Home1 success\"><div class=\"div-block-161\"><div class=\"am-paragraph-16 am-opacity-60 am-is-line-height-100\">Thank you!</div></div></div><div class=\"am-form-error-message w-form-fail\" tabindex=\"-1\" role=\"region\" aria-label=\"Partial - Home1 failure\"><div class=\"hide\">Oops! Something went wrong while submitting the form.</div></div></div><div class=\"am-social-proof-stripe is-light\"><div class=\"am-social-proof-stars\"><a rel=\"noopener\" href=\"https://www.g2.com/products/iramdani/reviews#reviews\" target=\"_blank\" class=\"am-social-proof-link w-inline-block\"><img src=\"cdn.prod.website-files.com/6350808bc45bd0c902af10e6/66a3b9b79fd4fe04bcc54f09_g2-stars-white.svg\" loading=\"lazy\" alt=\"5 stars G2 reviews\" class=\"am-image\" /></a><div class=\"am-vertical-divider is-light hide